class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        if num1 == '0' or num2 == '0':
            return '0'
        m, n = len(num1), len(num2)
        slots = [0] * (m + n)   # slots[k] accumulates the coefficient of 10^k
        a = [ord(c) - 48 for c in reversed(num1)]   # least significant digit first
        b = [ord(c) - 48 for c in reversed(num2)]
        for i, da in enumerate(a):
            if da == 0:
                continue
            for j, db in enumerate(b):
                slots[i + j] += da * db
        carry = 0
        for k in range(m + n):
            total = slots[k] + carry
            slots[k] = total % 10
            carry = total // 10
        # drop leading zeros (slots is least significant first)
        while len(slots) > 1 and slots[-1] == 0:
            slots.pop()
        return ''.join(str(d) for d in reversed(slots))

